static void Check(bool value,const std::string& text){if(!value)throw std::runtime_error(text);++checks;}
static void Near(float a,float b,const char* text){Check(std::abs(a-b)<.001f,text);}
static double Difference(const std::vector<unsigned char>& a,const std::vector<unsigned char>& b){Check(a.size()==b.size()&&!a.empty(),"comparable images");double sum=0;for(size_t i=0;i<a.size();++i)sum+=std::abs(int(a[i])-int(b[i]));return sum/a.size();}
struct Owned {std::filesystem::path path;~Owned(){std::error_code e;std::filesystem::remove(path,e);}};
static ui::Widget& Widget(ui::Document& d,const char* id){auto it=std::find_if(d.widgets.begin(),d.widgets.end(),[&](auto& w){return w.id==id;});if(it==d.widgets.end())throw std::runtime_error(id);return *it;}
